import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第五章 谁才是真正保护好了自己的人？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/5第五章 谁才是真正保护好了自己的人.md","filePath":"meditation/巴利文大藏经/5第五章 谁才是真正保护好了自己的人.md"}'),o={name:"meditation/巴利文大藏经/5第五章 谁才是真正保护好了自己的人.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第五章-谁才是真正保护好了自己的人" tabindex="-1">第五章 谁才是真正保护好了自己的人？ <a class="header-anchor" href="#第五章-谁才是真正保护好了自己的人" aria-label="Permalink to &quot;第五章 谁才是真正保护好了自己的人？&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部3相应5经/已自己守护经(憍萨罗相应/有偈篇/祇夜)</p><p>有个时候，骄萨罗国的波斯匿王来到佛陀的住所，顶礼佛陀后，波斯匿王坐下对佛陀说：“世尊，我独自静坐的时候，内心生起了这样的念想：「谁保护好了自己？谁没有保护好自己？」</p><p>世尊，我是这样回答这个问题的：任何人只要他们的身体行为做恶事，口说恶语，内心生起恶念，那么他们就没有保护好自己，就算有大象军团保护他们，有骑兵军团保护他们，有战车军团保护他们，有步兵军团保护他们，然而他们还是没有保护好自己，那是为什么呢？因为不管是大象军团、骑兵军团的保护，还是战车军团、步兵军团的保护，这些保护都是外在的保护，而不是内在本身的保护，他们的内在本身没有受到保护，所以他们无法保护好自己。</p><p>世尊，任何人只要他们的身体行为做善事，口说善语，内心生起善念，那么他们就已经保护好了自己，就算没有大象军团保护他们，没有骑兵军团保护他们，没有战车军团保护他们，没有步兵军团保护他们，然而他们还是已经保护好了自己，那是为什么呢？因为他们的身体行为做善事，口说善语，内心生起善念的缘故，让他们的内在本身受到了保护，这个保护是内在的保护而不是外在的保护，那些大象军团、骑兵军团的保护，那些战车军团、步兵军团的保护，这些保护都是外在的保护，而不是本身内在的保护，所以他们身体行为做善事，口说善语，内心生起善念就已经保护好了自己。”</p><p>佛陀说：“大王，正如你所说，确实是这样的！</p><p>任何人他们的身体行为做恶事，口说恶言，内心生起恶念他们就没有保护好他们自己本身。为什么呢？因为他们身体行为做恶事，口说恶言，内心生起恶念就破坏了内在本身的保护，所以说他们没有保护好他们自己本身。这个保护是内在本身的保护，是由内而外的保护，是由他们本身的行为、言语、念想而构建出来的保护，不是外在的保护，内在的保护坚固而持久。</p><p>大王，同样的道理，任何人他们的身体行为做善事，口说善言，内心生起善念他们就保护好了他们自己本身。为什么呢？因为他们身体行为做善事，口说善言，内心生起善念就维持了内在本身的保护，所以说他们就保护好了他们自己本身。这个保护是内在本身的保护，是由内而外的保护，是由他们本身的行为、言语、念想而构建出来的保护，不是外在的保护，内在的保护坚固而持久。</p><p>大王，身体行为做善事，口说善言，内心生起善念就能控制自己不做恶事，由此善于约束和管束自己在任何的时候，遇到任何的事物事情都不做恶事。</p><p>大王，善于约束和管束自己不去做恶的行为，不去说恶的言语，不去生起恶的念想的人，他们就是有羞耻心的人，他们知道什么事情应该做，什么事情不应该做。他们的身体行为会经常的去做善事，他们的嘴巴会经常的说善言，他们的内心会经常的生起善念。他们不会去做任何丁点的恶事，这些人就是保护好了他们内在本身的人，这些人才是真正保护好了自己的人。”</p><p>这时，佛陀说偈言：</p><p>「善哉自制身，善哉自制语。</p><p>善哉自制意，善哉制一切。</p><p>自制知耻者，云为守护人。」</p>',15)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
